import{_ as i,a0 as l,w as u,s as m,I as e,x as o,a1 as r,A as p,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何使用Tmux提高终端环境下的效率 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Tmux提高终端环境下的效率 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Tmux提高终端环境下的效率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Tmux提高终端环境下的效率 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140811 How to improve your productivity in terminal environment with Tmux","title":"如何使用Tmux提高终端环境下的效率","tag":"201410","desc":""},"relativePath":"201410/20140811 How to improve your productivity in terminal environment with Tmux.md","filePath":"[post].md"}'),a={name:"201410/20140811 How to improve your productivity in terminal environment with Tmux.md"};function d(x,t,T,g,f,b){const n=l("Link");return u(),m("div",null,[t[23]||(t[23]=e("h1",{id:"如何使用tmux提高终端环境下的效率",tabindex:"-1"},[o("如何使用Tmux提高终端环境下的效率 "),e("a",{class:"header-anchor",href:"#如何使用tmux提高终端环境下的效率","aria-label":"Permalink to “如何使用Tmux提高终端环境下的效率”"},"​")],-1)),t[24]||(t[24]=e("p",null,"鼠标的发明是了不起的创新，它让电脑更加接近普通人。但从程序员和系统管理员的角度，使用电脑工作时，手一旦离开键盘，就会有些分心。",-1)),t[25]||(t[25]=e("p",null,"作为一名系统管理员，我大量的工作都需要在终端环境下。打开很多标签，然后在多个终端之间切换窗口会让我慢下来。尤其是当我的服务器出问题的时候，我不能浪费任何时间！",-1)),t[26]||(t[26]=e("p",null,[e("img",{src:"https://farm6.staticflickr.com/5563/14853747084_e14cf18e8f_z.jpg",alt:""})],-1)),e("p",null,[r(n,{href:"http://tmux.sourceforge.net/"},{default:p(()=>[...t[0]||(t[0]=[o("Tmux",-1)])]),_:1}),t[1]||(t[1]=o("是我日常工作必要的工具之一。我可以借助Tmux构建出复杂的开发环境，同时还可以在一旁进行SSH远程连接。我可以开出很多窗口，将其拆分成很多面板，接管和分离会话等等。掌握了Tmux之后，你就可以扔掉鼠标了（只是个玩笑:D）。",-1))]),t[27]||(t[27]=s(`<p>Tmux（&quot;Terminal Multiplexer&quot;的简称）可以让我们在单个屏幕的灵活布局下开出很多终端，我们就可以协作地使用它们。举个例子，在一个面板中，我们用Vim修改一些配置文件，在另一个面板，我们使用<code>irssi</code>聊天，而在其余的面板，可以跟踪一些日志。然后，我们还可以打开新的窗口来升级系统，再开一个新窗口来进行服务器的ssh连接。在这些窗口面板间浏览切换和创建它们一样简单。它的高度可配置和可定制的，让其成为你心中的延伸</p><h3 id="在linux-osx下安装tmux" tabindex="-1">在Linux/OSX下安装Tmux <a class="header-anchor" href="#在linux-osx下安装tmux" aria-label="Permalink to “在Linux/OSX下安装Tmux”">​</a></h3><p>你可以通过编译软件源或者通过系统包管理器的方式安装，我建议使用包管理器，这样比编译更快更简单</p><h4 id="osx" tabindex="-1">OSX: <a class="header-anchor" href="#osx" aria-label="Permalink to “OSX:”">​</a></h4><pre><code># sudo brew install tmux
# sudo port install tmux
</code></pre><h4 id="debian-ubuntu" tabindex="-1">Debian/Ubuntu: <a class="header-anchor" href="#debian-ubuntu" aria-label="Permalink to “Debian/Ubuntu:”">​</a></h4><pre><code># sudo apt-get install tmux
</code></pre>`,7)),e("p",null,[t[3]||(t[3]=o("####RHEL/CentOS/Fedora(RHEL/CentOS 要求 ",-1)),r(n,{href:"http://xmodulo.com/2013/03/how-to-set-up-epel-repository-on-centos.html"},{default:p(()=>[...t[2]||(t[2]=[o("EPEL repo",-1)])]),_:1}),t[4]||(t[4]=o("):####",-1))]),t[28]||(t[28]=s(`<pre><code>$ sudo yum install tmux
</code></pre><p>####Archlinux:####</p><pre><code>$ sudo pacman -S tmux
</code></pre><h3 id="使用不同会话工作" tabindex="-1">使用不同会话工作 <a class="header-anchor" href="#使用不同会话工作" aria-label="Permalink to “使用不同会话工作”">​</a></h3><p>使用Tmux的最好方式是使用会话的方式，这样你就可以以你想要的方式，将任务和应用组织到不同的会话中。如果你想改变一个会话，会话里面的任何工作都无须停止或者杀掉。让我们来看看这是怎么工作的。</p><p>让我们开始一个叫做&quot;session&quot;的会话，并且运行top命令</p><pre><code>$ tmux new -s new session
$ top
</code></pre><p>然后输入<strong>CTRL-b d</strong>从此会话脱离，想要重新连接此会话，需输入：</p><pre><code>$ tmux attach-session -t session
</code></pre><p>之后你会看到top操作仍然运行在重新连接的会话上。</p><p>一些管理sessions的命令：</p><pre><code>$ tmux list-session
$ tmux new-session &lt;会话名&gt;
$ tmux attach-session -t &lt;会话名&gt;
$ tmux rename-session -t &lt;会话名&gt;
$ tmux choose-session -t &lt;会话名&gt;
$ tmux kill-session -t &lt;会话名&gt;
</code></pre><h3 id="使用不同的窗口工作" tabindex="-1">使用不同的窗口工作 <a class="header-anchor" href="#使用不同的窗口工作" aria-label="Permalink to “使用不同的窗口工作”">​</a></h3><p>很多情况下，你需要在一个会话中运行多个命令，执行多个任务。我们可以在一个会话的多个窗口里组织他们。在现代的GUI终端（比如 iTerm或者Konsole），一个窗口被视为一个标签。在会话中配置了我们默认的环境之后，我们就能够在一个会话中创建许多我们需要的窗口。窗口就像运行在会话中的应用程序，当我们脱离当前会话的时候，它仍在持续，让我们来看一个例子：</p><pre><code>$ tmux new -s my_session
</code></pre><p><img src="https://farm6.staticflickr.com/5583/14853747014_442b3742fa_z.jpg" alt=""></p><p>按下<strong>CTRL-b c</strong></p><p>这将会创建一个新的窗口，然后屏幕的光标移向它。现在你就可以在新窗口下运行你的新应用。你可以修改你当前窗口的名字。在目前的例子里，我运行的top程序，所以top就是该窗口的名字</p><p>如果你想要重命名，只需要按下：</p><p><strong>CTRL-b</strong></p><p>状态条将会改变，这时你将可以重命名当前的窗口</p><p><img src="https://farm6.staticflickr.com/5579/14855868482_d52516a357_z.jpg" alt=""></p><p>一旦在一个会话中创建多个窗口，我们需要在这些窗口间移动的办法。窗口像数组一样组织在一起，从0开始用数字标记每个窗口，想要快速跳转到其余窗口：</p><p><strong>CTRL-b &lt;窗口号&gt;</strong></p><p>如果我们给窗口起了名字，我们可以使用下面的命令找到它们：</p><p><strong>CTRL-b f</strong></p><p>也可以列出所有窗口：</p><p><strong>CTRL-b w</strong></p><p>按照顺序切换到不同的窗口：</p><p><strong>CTRL-b n</strong>（到达下一个窗口） <strong>CTRL-b p</strong>（到达上一个窗口）</p><p>想要离开一个窗口，可以输入 exit 或者：</p><p><strong>CTRL-b &amp;</strong></p><p>关闭窗口之前，你需要确认一下。</p><h3 id="把窗口分成许多面板" tabindex="-1">把窗口分成许多面板 <a class="header-anchor" href="#把窗口分成许多面板" aria-label="Permalink to “把窗口分成许多面板”">​</a></h3><p>有时候你在编辑器工作的同时，需要查看日志文件。在编辑的同时追踪日志真的很有帮助。Tmux可以让我们把窗口分成许多面板。举个例子，我们可以创建一个控制台监测我们的服务器，同时用编辑器构造复杂的开发环境，这样就能同时进行编译和调试了。</p><p>让我们创建另一个Tmux会话，让其以面板的方式工作。首先，如果我们在某个会话中，那就从Tmux会话中脱离出来：</p><p><strong>CTRL-b d</strong></p><p>开始一个叫做&quot;panes&quot;的新会话：</p><pre><code>$ tmux new -s panes
</code></pre><p>你可以水平或者竖直分割一个窗口，水平分割输入：</p><p><strong>CRTL-b &quot;</strong></p><p>现在你就拥有两个面板，现在我们竖直分割：</p><p><strong>CRTL-b %</strong></p><p>又增加了两个：</p><p><img src="https://farm4.staticflickr.com/3881/14669677417_bc1bdce255_z.jpg" alt=""></p><p>在他们之间移动：</p><p><strong>CTRL-b &lt;光标键&gt;</strong></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3>`,48)),e("p",null,[t[7]||(t[7]=o("我希望这篇教程能对你有作用。此外，像",-1)),r(n,{href:"https://github.com/tmuxinator/tmuxinator"},{default:p(()=>[...t[5]||(t[5]=[o("Tmuxinator",-1)])]),_:1}),t[8]||(t[8]=o(" 或者 ",-1)),r(n,{href:"https://github.com/jimeh/tmuxifier"},{default:p(()=>[...t[6]||(t[6]=[o("Tmuxifier",-1)])]),_:1}),t[9]||(t[9]=o("这样的工具，可以简化Tmux会话，窗口和面板的创建及加载，你可以很容易就配置Tmux。如果你没有使用过这些，尝试一下吧！",-1))]),t[29]||(t[29]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=o("via: ",-1)),r(n,{href:"http://xmodulo.com/2014/08/improve-productivity-terminal-environment-tmux.html"},{default:p(()=>[...t[10]||(t[10]=[o("http://xmodulo.com/2014/08/improve-productivity-terminal-environment-tmux.html",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=o("作者：",-1)),r(n,{href:"http://xmodulo.com/author/valerio"},{default:p(()=>[...t[12]||(t[12]=[o("Christopher Valerio",-1)])]),_:1}),t[16]||(t[16]=o(" 译者：",-1)),r(n,{href:"https://github.com/su-kaiyao"},{default:p(()=>[...t[13]||(t[13]=[o("su-kaiyao",-1)])]),_:1}),t[17]||(t[17]=o(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=o("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[18]||(t[18]=[o("LCTT",-1)])]),_:1}),t[21]||(t[21]=o(" 原创翻译，",-1)),r(n,{href:"http://linux.cn/"},{default:p(()=>[...t[19]||(t[19]=[o("Linux中国",-1)])]),_:1}),t[22]||(t[22]=o(" 荣誉推出",-1))])])}const v=i(a,[["render",d]]);export{L as __pageData,v as default};
